    import time

    LANGUAGE_WRAPPER = 'Let S be a finite set of distinct real numbers with unknown size and mean. Consider two arithmetic progressions A and B defined as follows: A has {u_count} terms, first term {a1_first}, and common difference {d1_diff}; B has {v_count} terms, first term {a2_first}, and common difference {d2_diff}. Assume S is disjoint from both A and B. It is given that the mean of S ∪ A equals the mean of S plus {delta_a}, the mean of S ∪ B equals the mean of S plus {delta_b}, and the mean of S ∪ (A ∪ B) equals the mean of S plus {delta_ab}. Determine the mean of S.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
for _ in range(1000):
    n = rng.randint(30, 200)  # size of S, hidden
    # pick two small divisors of n for progression sizes
    divs = [d for d in range(3, min(12, n)) if n % d == 0]
    if len(divs) < 2:
        continue
    u_count, v_count = rng.sample(divs, 2)
    # choose base mean (hidden answer) as a moderate integer
    m = rng.randint(200, 2000)
    # choose integer delta_a = delta_b = t so that delta_ab becomes integer
    D = n + u_count + v_count
    h = math.gcd(D, 2*n + u_count + v_count)
    t_base = rng.randint(1, 5)
    t = t_base * (D // h)  # ensures delta_ab integer
    delta_a = t
    delta_b = t
    # ensure nontrivial denominator for solving n later: t/u - t/v != 0 (true since u != v)
    # choose even differences to make first terms integers
    d1_diff = 2 * rng.randint(1, 6)
    d2_diff = 2 * rng.randint(1, 6)
    # since u|n and v|n, (n+u)/u and (n+v)/v are integers; set averages accordingly
    x1 = (n + u_count) // u_count
    x2 = (n + v_count) // v_count
    A_avg = m + t * x1
    B_avg = m + t * x2
    # choose first terms consistent with averages
    a1_first = A_avg - (u_count - 1) * d1_diff // 2
    a2_first = B_avg - (v_count - 1) * d2_diff // 2
    # sanity checks: keep numbers within reasonable bounds
    if abs(a1_first) > 10**9 or abs(a2_first) > 10**9:
        continue
    # compute delta_ab as integer
    delta_ab = (t * (n + u_count) + t * (n + v_count)) // (n + u_count + v_count)
    # extra difficulty guard: ensure n is not tiny and deltas are nonzero
    if delta_a == 0 or delta_b == 0:
        continue
    # return assignment
    return {
        'u_count': u_count,
        'a1_first': a1_first,
        'd1_diff': d1_diff,
        'v_count': v_count,
        'a2_first': a2_first,
        'd2_diff': d2_diff,
        'delta_a': delta_a,
        'delta_b': delta_b,
        'delta_ab': delta_ab
    }
raise RuntimeError('generator failed to find a valid instance')

    def verifier(assign):
# recompute, validate domain constraints, and return (True, answer)
try:
    from fractions import Fraction
    u = assign['u_count']
    v = assign['v_count']
    a1 = assign['a1_first']
    a2 = assign['a2_first']
    d1 = assign['d1_diff']
    d2 = assign['d2_diff']
    da = assign['delta_a']
    db = assign['delta_b']
    dab = assign['delta_ab']
except KeyError:
    # missing fields
    return (False, None)
# Basic domain checks
if not (isinstance(u, int) and isinstance(v, int) and isinstance(a1, int) and isinstance(a2, int) and isinstance(d1, int) and isinstance(d2, int) and isinstance(da, int) and isinstance(db, int) and isinstance(dab, int)):
    return (False, None)
if u < 3 or v < 3 or u == v:
    return (False, None)
if d1 <= 0 or d2 <= 0 or d1 % 2 != 0 or d2 % 2 != 0:
    return (False, None)
if da == 0 or db == 0:
    return (False, None)
# Progression averages
A_avg = Fraction(a1) + Fraction((u - 1) * d1, 2)
B_avg = Fraction(a2) + Fraction((v - 1) * d2, 2)
# Solve for n via the mean-shift identities:
# da = u*(A_avg - m)/(n + u), db = v*(B_avg - m)/(n + v)
# -> n = (A_avg - B_avg - (da - db)) / (da/u - db/v)
denom = Fraction(da, u) - Fraction(db, v)
if denom == 0:
    # would make problem trivial/undefined
    return (False, None)
n_val = (A_avg - B_avg - Fraction(da - db, 1)) / denom
if n_val.denominator != 1:
    # size should be integer
    return (False, None)
n = n_val.numerator
if n < 25:
    # enforce difficulty: sufficiently large set
    return (False, None)
# Compute mean m
m_val = A_avg - Fraction(da * (n + u), u)
# Validate against B condition for consistency
m_val_check = B_avg - Fraction(db * (n + v), v)
if m_val != m_val_check:
    return (False, None)
# Validate combined shift
dab_check = Fraction(u) * (A_avg - m_val) + Fraction(v) * (B_avg - m_val)
dab_check = dab_check / Fraction(n + u + v, 1)
if dab_check.denominator != 1 or dab_check.numerator != dab:
    return (False, None)
# Final answer must be numeric; ensure integer
if m_val.denominator != 1:
    # we expect integer mean for this family
    return (False, None)
answer = m_val.numerator
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

